// Marks images that show AI-generated people. Amazon asks sellers to label product images whose
// photorealistic people were generated by AI (2026). The standard way to say an image was made by
// a generative model is IPTC's digital source type "trainedAlgorithmicMedia", carried in XMP;
// Basira writes it into the PNG and lists the files in the export README.
// Check Amazon's current wording before relying on this as the only label.
import { crc32 } from "./zip.mjs";

export const AI_SOURCE_TYPE = "http://cv.iptc.org/newscodes/digitalsourcetype/trainedAlgorithmicMedia";

export function aiXmp() {
  return `<?xpacket begin="﻿" id="W5M0MpCehiHzreSzNTczkc9d"?><x:xmpmeta xmlns:x="adobe:ns:meta/"><rdf:RDF xmlns:rdf="http://www.w3.org/1999/02/22-rdf-syntax-ns#"><rdf:Description rdf:about="" xmlns:Iptc4xmpExt="http://iptc.org/std/Iptc4xmpExt/2008-02-29/" Iptc4xmpExt:DigitalSourceType="${AI_SOURCE_TYPE}"/></rdf:RDF></x:xmpmeta><?xpacket end="w"?>`;
}

/** A copy of the PNG with an XMP iTXt chunk right after IHDR. Non-PNG input comes back unchanged. */
export function labelPng(png, xmp = aiXmp()) {
  const buf = Buffer.from(png);
  if (buf.length < 33 || buf.readUInt32BE(0) !== 0x89504e47) return buf;
  const ihdrEnd = 8 + 4 + 4 + buf.readUInt32BE(8) + 4;
  const data = Buffer.concat([Buffer.from("XML:com.adobe.xmp\0\0\0\0\0", "latin1"), Buffer.from(xmp, "utf8")]);
  const type = Buffer.from("iTXt", "latin1");
  const len = Buffer.alloc(4); len.writeUInt32BE(data.length);
  const crc = Buffer.alloc(4); crc.writeUInt32BE(crc32(Buffer.concat([type, data])) >>> 0);
  return Buffer.concat([buf.subarray(0, ihdrEnd), len, type, data, crc, buf.subarray(ihdrEnd)]);
}

/** Whether a PNG carries the AI label. */
export function hasAiLabel(png) { return Buffer.from(png).includes(Buffer.from(AI_SOURCE_TYPE)); }
